if (!defined('ABSPATH')) { exit; }
function emdop8_words($html){$text=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes($html))));if($text==='')return 0;preg_match_all('/[\p{L}\p{M}]+(?:[’\x{27}’-][\p{L}\p{M}]+)*/u',$text,$m);return count($m[0]);}
function emdop8_cat($name,$slug,$en_name,$en_slug,$fallback=''){$term=get_term_by('slug',$slug,'category');if(!$term&&$fallback!=='')$term=get_term_by('name',$fallback,'category');if(!$term)$term=get_term_by('name',$name,'category');if(!$term){$made=wp_insert_term($name,'category',array('slug'=>$slug));if(is_wp_error($made))throw new Exception($made->get_error_message());$term=get_term((int)$made['term_id'],'category');}update_term_meta($term->term_id,'_en_US_name',$en_name);update_term_meta($term->term_id,'_en_US_slug',$en_slug);update_term_meta($term->term_id,'_en_US_published','1');return (int)$term->term_id;}
