foreach($files as $file){$a=require $file;foreach(array('key','priority','slug','en_slug','topic','title','en_title','excerpt','en_excerpt','content','en_content','min_es','min_en') as $f){if(!isset($a[$f])||$a[$f]==='')throw new Exception(basename($file).' missing '.$f);}if(!isset($cats[$a['topic']]))throw new Exception('Unexpected topic '.$a['topic']);if((int)$a['priority']<35||(int)$a['priority']>38)throw new Exception('Unexpected priority '.(int)$a['priority']);$product=$product_slugs[$a['topic']];$content=str_replace('__PRODUCT_CAT__',$product,$a['content']);$en=str_replace('__PRODUCT_CAT__',$product,$a['en_content']);$wes=emdop8_words($content);$wen=emdop8_words($en);if($wes<(int)$a['min_es']||$wen<(int)$a['min_en'])throw new Exception($a['key'].' too short ES='.$wes.'/'.(int)$a['min_es'].' EN='.$wen.'/'.(int)$a['min_en']);$existing=emdop8_existing($a['key'],$a['slug']);$new=$existing<=0;$post=array('post_type'=>'post','post_status'=>'publish','post_author'=>$author,'post_title'=>wp_strip_all_tags($a['title']),'post_name'=>sanitize_title($a['slug']),'post_excerpt'=>wp_strip_all_tags($a['excerpt']),'post_content'=>$content);if($existing)$post['ID']=$existing;$res=$existing?wp_update_post($post,true):wp_insert_post($post,true);if(is_wp_error($res))throw new Exception($a['key'].': '.$res->get_error_message());$id=(int)$res;wp_set_post_categories($id,array($guide,$cats[$a['topic']]),false);update_post_meta($id,'_emdo_authority_key',$a['key']);update_post_meta($id,'_emdo_priority_plan','38');update_post_meta($id,'_emdo_priority_order',(string)$a['priority']);update_post_meta($id,'_emdo_priority_batch','8');update_post_meta($id,'_en_US_post_title',wp_strip_all_tags($a['en_title']));update_post_meta($id,'_en_US_post_name',sanitize_title($a['en_slug']));update_post_meta($id,'_en_US_post_excerpt',wp_strip_all_tags($a['en_excerpt']));update_post_meta($id,'_en_US_post_content',$en);update_post_meta($id,'_en_US_ready','1');update_post_meta($id,'_en_US_published','1');upda